<?php
namespace App\Http\Controllers;
use App\Models\Person; use App\Models\TranscriptIssue; use Barryvdh\DomPDF\Facade\Pdf; use Endroid\QrCode\QrCode; use Endroid\QrCode\Writer\SvgWriter; use Illuminate\Http\Request; use Illuminate\Support\Str; use Symfony\Component\HttpFoundation\Response;
class TranscriptController extends Controller {
 public function issue(Request $request,Person $person): Response { abort_unless($request->user()->hasPermission('transcripts.issue')||$request->user()->person?->is($person),403); abort_if($person->programEnrollments()->whereHas('termEnrollments',fn($q)=>$q->whereHas('registrations'))->doesntExist(),422,'No academic record.'); $token=Str::random(64); $issue=TranscriptIssue::create(['person_id'=>$person->id,'serial_number'=>'DEMO-'.now()->format('Ymd').'-'.Str::upper(Str::random(8)),'verification_token'=>$token,'issued_by'=>$request->user()->id,'issued_at'=>now()]); $url=route('transcripts.verify',$token); $qr=(new SvgWriter)->write(new QrCode($url))->getDataUri(); $person->load('programEnrollments.termEnrollments.registrations.grade','programEnrollments.termEnrollments.registrations.section.courseVersion.course'); $pdf=Pdf::loadView('transcript',compact('person','issue','qr'))->setPaper('a4'); $bytes=$pdf->output(); $issue->update(['document_sha256'=>hash('sha256',$bytes)]); return response($bytes,200,['Content-Type'=>'application/pdf','Content-Disposition'=>'inline; filename="'.$issue->serial_number.'.pdf"']); }
 public function verify(string $token): Response { $issue=TranscriptIssue::where('verification_token',$token)->firstOrFail(); return response()->view('verify-transcript',compact('issue')); }
}
